void printVariant(IRPrinter& printer, const CreatorRecord& variant)
{
    printer.out().print(nameOf(variant.kind()));
    switch (variant.kind()) {
    case CreatorRecord::Kind::None: case CreatorRecord::Kind::ChainStep:
        return;
    case CreatorRecord::Kind::Entrypoint:
        printRecord(printer, variant.as<CreatorRecord::Entrypoint>());
        return;
    case CreatorRecord::Kind::Version:
        printRecord(printer, variant.as<CreatorRecord::Version>());
        return;
    case CreatorRecord::Kind::Coroutine:
        printRecord(printer, variant.as<CreatorRecord::Coroutine>());
        return;
    case CreatorRecord::Kind::BoundFunction:
        printRecord(printer, variant.as<CreatorRecord::BoundFunction>());
        return;
    case CreatorRecord::Kind::ResultWrapper:
        printRecord(printer, variant.as<CreatorRecord::ResultWrapper>());
        return;
    case CreatorRecord::Kind::ResultWorker:
        printRecord(printer, variant.as<CreatorRecord::ResultWorker>());
        return;
    case CreatorRecord::Kind::ParameterWrapper:
        printRecord(printer, variant.as<CreatorRecord::ParameterWrapper>());
        return;
    case CreatorRecord::Kind::Continuation:
        printRecord(printer, variant.as<CreatorRecord::Continuation>());
        return;
    case CreatorRecord::Kind::Serializer:
        printRecord(printer, variant.as<CreatorRecord::Serializer>());
        return;
    case CreatorRecord::Kind::Parser:
        printRecord(printer, variant.as<CreatorRecord::Parser>());
        return;
    case CreatorRecord::Kind::Validator:
        printRecord(printer, variant.as<CreatorRecord::Validator>());
        return;
    case CreatorRecord::Kind::StubBody:
        printRecord(printer, variant.as<CreatorRecord::StubBody>());
        return;
    }
    RELEASE_ASSERT_NOT_REACHED();
}

