void printFields(IRPrinter& printer, const FunctionRecord& record)
{
    if (record.name)
        printer.field("name"_s, record.name);
    printer.field("module"_s, record.module);
    if (record.position)
        printer.field("position"_s, record.position);
    if (!isZero(record.text)) {
        printer.beginField("text"_s);
        printRecord(printer, record.text);
    }
    if (record.kind != FunctionKind::Plain)
        printer.field("kind"_s, record.kind);
    if (record.role != FunctionRole::Source)
        printer.field("role"_s, record.role);
    if (!record.flags.isEmpty())
        printer.field("flags"_s, record.flags);
    if (record.length)
        printer.field("length"_s, record.length);
    if (record.enclosingRuntimeFunction)
        printer.field("enclosingRuntimeFunction"_s, record.enclosingRuntimeFunction);
    if (!record.captures.isEmpty()) {
        printer.beginField("captures"_s);
        printer.list(record.captures, [&](const auto& element) {
            printRecord(printer, element);
        });
    }
    printer.beginField("thisType"_s);
    printRecord(printer, record.thisType);
    if (!record.parameters.isEmpty()) {
        printer.beginField("parameters"_s);
        printer.list(record.parameters, [&](const auto& element) {
            printRecord(printer, element);
        });
    }
    if (!record.results.isEmpty()) {
        printer.beginField("results"_s);
        printer.list(record.results, [&](const auto& element) {
            printRecord(printer, element);
        });
    }
    if (!record.functionTypes.isEmpty()) {
        printer.beginField("functionTypes"_s);
        printer.list(record.functionTypes, [&](const auto& element) {
            printer.print(element);
        });
    }
    if (!printer.printsEngineFields())
        return;
    if (!record.capabilities.isEmpty())
        printer.field("capabilities"_s, record.capabilities);
    if (!isZero(record.derivation)) {
        printer.beginField("derivation"_s);
        printRecord(printer, record.derivation);
    }
    if (!isZero(record.creator)) {
        printer.beginField("creator"_s);
        printVariant(printer, record.creator);
    }
    if (record.constructedClass)
        printer.field("constructedClass"_s, record.constructedClass);
    if (!record.inlineFrames.isEmpty()) {
        printer.beginField("inlineFrames"_s);
        printer.list(record.inlineFrames, [&](const auto& element) {
            printRecord(printer, element);
        });
    }
}

